beforeExample:
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.eclipse.core.runtime.Platform;
import org.eclipse.core.runtime.content.IContentType;

public class Example {
    private Set<IContentType> contentTypes;
    public void someMethod(Object editor) {
        String name = "file.txt";
        // Matched line:
        Set<IContentType> types = new HashSet<>(Arrays.asList(Platform.getContentTypeManager().findContentTypesFor(name)));
        System.out.println(types);
        this.contentTypes = types;
    }
}

afterExample:
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;
import org.eclipse.core.runtime.Platform;
import org.eclipse.core.runtime.content.IContentType;

public class Example {
    private Set<IContentType> contentTypes;
    public void someMethod(Object editor) {
        String name = "file.txt";
        // Changed line:
        Set<IContentType> types = new LinkedHashSet<>(Arrays.asList(Platform.getContentTypeManager().findContentTypesFor(name)));
        System.out.println(types);
        this.contentTypes = types;
    }
}

negativeExample:
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.eclipse.core.runtime.Platform;
import org.eclipse.core.runtime.content.IContentType;

public class NegativeExample {
    // Should NOT match because it's a field, not a local variable
    private Set<IContentType> contentTypes = new HashSet<>(Arrays.asList(Platform.getContentTypeManager().findContentTypesFor("file.txt")));

    public void anotherMethod() {
        Set<String> anotherSet = new LinkedHashSet<>(); // Already LinkedHashSet
        System.out.println(anotherSet);

        Set<Integer> yetAnotherSet = new HashSet<>(); // No-arg constructor, still matches as $args$ can be empty
        System.out.println(yetAnotherSet);
    }
}
